// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Unit tests for server list-empty guard, id reader
// Flo: build JSON values > call listEmpt, jsonIden > assert verdicts
// I/O: JSON null, string, array values > pass or fail
// ===================================================================
const std = @import("std"); const serv = @import("sv-main-serv.zig");
const tszz = std.testing;
test "listEmpt knows empty list strings without parsing them" { try tszz.expect(serv.listEmpt(.null)); try tszz.expect(serv.listEmpt(.{ .string = "[]" })); try tszz.expect(serv.listEmpt(.{ .string = " [ ] " })); try tszz.expect(serv.listEmpt(.{ .string = "" })); try tszz.expect(!serv.listEmpt(.{ .string = "[\"a\"]" })); try tszz.expect(!serv.listEmpt(.{ .string = "[{}]" })); try tszz.expect(serv.listEmpt(.{ .string = "\t\r\n" })); try tszz.expect(!serv.listEmpt(.{ .string = "x" })); try tszz.expect(!serv.listEmpt(.{ .bool = true })); try tszz.expect(!serv.listEmpt(.{ .integer = 0 })); }
fn idenOf(aren: std.mem.Allocator, text: []const u8, keyz: []const u8) ?[]const u8 { const root = std.json.parseFromSliceLeaky(std.json.Value, aren, text, .{}) catch unreachable; return serv.jsonIden(aren, root, keyz); }
test "jsonIden keeps a string id as it is" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); try tszz.expectEqualStrings("tab-1", idenOf(aren.allocator(), "{\"tabId\":\"tab-1\"}", "tabId").?); try tszz.expectEqualStrings("", idenOf(aren.allocator(), "{\"tabId\":\"\"}", "tabId").?); }
test "jsonIden turns a whole number into its decimal text" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); try tszz.expectEqualStrings("7", idenOf(allo, "{\"tabId\":7}", "tabId").?); try tszz.expectEqualStrings("0", idenOf(allo, "{\"tabId\":0}", "tabId").?); try tszz.expectEqualStrings("-3", idenOf(allo, "{\"tabId\":-3}", "tabId").?); try tszz.expectEqualStrings("9223372036854775807", idenOf(allo, "{\"tabId\":9223372036854775807}", "tabId").?); }
test "jsonIden refuses float, bool, null, array, object, missing key and a non-object root" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); for ([_][]const u8{ "{\"tabId\":7.5}", "{\"tabId\":true}", "{\"tabId\":null}", "{\"tabId\":[7]}", "{\"tabId\":{}}", "{\"other\":7}", "[7]", "7" }) |text| try tszz.expect(idenOf(allo, text, "tabId") == null); }
test "a number id and its string twin give the same session key" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const allo = aren.allocator(); try tszz.expectEqualStrings(idenOf(allo, "{\"tabId\":12}", "tabId").?, idenOf(allo, "{\"tabId\":\"12\"}", "tabId").?); }
test "guarChec guards exactly the two list keys and nothing near them" { try tszz.expect(serv.guarChec("cmrn_hist")); try tszz.expect(serv.guarChec("cmrn_favs")); for ([_][]const u8{ "", "cmrn_hist ", "cmrn_histx", "CMRN_HIST", "cmrn_fav", "cmrn_favs2", "cmrn_labl_v" }) |keyz| try tszz.expect(!serv.guarChec(keyz)); }
test "strzLess is plain byte order: strict, prefix first, upper case before lower" { try tszz.expect(serv.strzLess({}, "a", "b")); try tszz.expect(!serv.strzLess({}, "b", "a")); try tszz.expect(!serv.strzLess({}, "a", "a")); try tszz.expect(serv.strzLess({}, "", "a")); try tszz.expect(serv.strzLess({}, "a", "ab")); try tszz.expect(serv.strzLess({}, "B", "a")); }
test "plusWrit writes the prefix, then the value as compact JSON" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const plus = try std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), "[ \"y\", \"m\", [5, 10], \"s\" ]", .{}); var bufz: [128]u8 = undefined; var wrtr: std.Io.Writer = .fixed(&bufz); try serv.plusWrit(&wrtr, plus, ",\"plus\":"); try tszz.expectEqualStrings(",\"plus\":[\"y\",\"m\",[5,10],\"s\"]", wrtr.buffered()); }
test "optiStrzWrit writes a comma, the key, then an escaped string or null" { var bufz: [128]u8 = undefined; var wrtr: std.Io.Writer = .fixed(&bufz); try serv.optiStrzWrit(&wrtr, "k", "a\"b\n"); try tszz.expectEqualStrings(",\"k\":\"a\\\"b\\n\"", wrtr.buffered()); var buf2: [64]u8 = undefined; var wrt2: std.Io.Writer = .fixed(&buf2); try serv.optiStrzWrit(&wrt2, "x", null); try tszz.expectEqualStrings(",\"x\":null", wrt2.buffered()); var buf3: [64]u8 = undefined; var wrt3: std.Io.Writer = .fixed(&buf3); try serv.optiStrzWrit(&wrt3, "e", ""); try tszz.expectEqualStrings(",\"e\":\"\"", wrt3.buffered()); }
test "jsonStrz answers only for a string field of an object" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const root = try std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), "{\"a\":\"x\",\"b\":1,\"c\":null,\"d\":\"\"}", .{}); try tszz.expectEqualStrings("x", serv.jsonStrz(root, "a").?); try tszz.expectEqualStrings("", serv.jsonStrz(root, "d").?); for ([_][]const u8{ "b", "c", "zz" }) |keyz| try tszz.expect(serv.jsonStrz(root, keyz) == null); try tszz.expect(serv.jsonStrz(.null, "a") == null); }
test "jsonBool answers only for a true or false field" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const root = try std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), "{\"t\":true,\"f\":false,\"s\":\"true\",\"n\":1}", .{}); try tszz.expectEqual(@as(?bool, true), serv.jsonBool(root, "t")); try tszz.expectEqual(@as(?bool, false), serv.jsonBool(root, "f")); for ([_][]const u8{ "s", "n", "zz" }) |keyz| try tszz.expect(serv.jsonBool(root, keyz) == null); try tszz.expect(serv.jsonBool(.null, "t") == null); }
test "jsonInte reads whole numbers, truncates a finite float, refuses text, bool and huge floats" { var aren = std.heap.ArenaAllocator.init(tszz.allocator); defer aren.deinit(); const root = try std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), "{\"a\":5,\"b\":-7,\"c\":5.0,\"d\":5.9,\"e\":-5.9,\"f\":1e19,\"g\":\"5\",\"h\":true,\"i\":0}", .{}); try tszz.expectEqual(@as(?i64, 5), serv.jsonInte(root, "a")); try tszz.expectEqual(@as(?i64, -7), serv.jsonInte(root, "b")); try tszz.expectEqual(@as(?i64, 5), serv.jsonInte(root, "c")); try tszz.expectEqual(@as(?i64, 5), serv.jsonInte(root, "d")); try tszz.expectEqual(@as(?i64, -5), serv.jsonInte(root, "e")); try tszz.expectEqual(@as(?i64, 0), serv.jsonInte(root, "i")); for ([_][]const u8{ "f", "g", "h", "zz" }) |keyz| try tszz.expect(serv.jsonInte(root, keyz) == null); }
